    @Test void feeEvidenceMatchesActualPartialAndCompletedIcebergWithoutDoubleCounting() {
        var ticket = new PaperTrading.Ticket(stock.getId(),null,null,9,"BUY","CASH","ICEBERG","LIMIT","DAY",
                new BigDecimal("100"),null,2,null,null,null,UUID.randomUUID().toString());
        String id = submit(ticket);
        paper.process(id);
        var partial = feeEvidence.read(user.getEmail(),id);
        assertEquals(com.example.investsmart.dto.TicketFeeEvidence.Verification.MATCHED,partial.verification());
        assertEquals(new BigDecimal("0.15"),partial.reconciledFee());
        paper.process(id); paper.process(id);
        var balance = users.findById(user.getId()).orElseThrow().getVirtualBalance();
        var complete = feeEvidence.read(user.getEmail(),id);
        assertEquals(com.example.investsmart.dto.TicketFeeEvidence.Verification.MATCHED,complete.verification());
        assertEquals(new BigDecimal("0.27"),complete.detailFee());
        assertEquals(new BigDecimal("0.27"),complete.recordedFee());
        assertEquals(new BigDecimal("0.27"),complete.reconciledFee());
        String fillId=db.queryForObject("SELECT id FROM paper_fills WHERE ticket_id=? AND leg_number=0",String.class,id);
        assertEquals(com.example.investsmart.dto.EquityLegacyEvidence.Verification.MATCHED_DUPLICATE,
                legacyEvidence.read(user.getEmail(),fillId).verification());
        assertEquals(complete,feeEvidence.read(user.getEmail(),id));
        assertEquals(balance,users.findById(user.getId()).orElseThrow().getVirtualBalance());
    }
    @Test void providerFailureIsReportedAsRetryable503WithoutLeakingDiagnosticsOrWritingOrders()throws Exception{
        when(market.getQuote(any(MarketInstrument.class))).thenThrow(new RuntimeException("private-provider-token-or-response"));
        var cookie=new jakarta.servlet.http.Cookie(com.example.investsmart.security.SecurityAccounts.COOKIE,accounts.issue(user,new org.springframework.mock.web.MockHttpServletRequest(),new org.springframework.mock.web.MockHttpServletResponse()));
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/orders/paper/preview").cookie(cookie).with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).contentType("application/json").content(json.writeValueAsString(ticket("CASH","MARKET",1,null,null,null))))
            .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isServiceUnavailable())
            .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.message").value(org.hamcrest.Matchers.containsString("Fresh executable market data")))
            .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("private-provider"))));
        cash("10000");assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM paper_tickets WHERE user_id=?",Integer.class,user.getId()));
        assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM settlement_accounts WHERE user_id=?",Integer.class,user.getId()));
    }
    static class MutableClock extends Clock {Instant at=Instant.parse("2026-11-11T04:30:00Z");public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return Clock.fixed(at,z);}public Instant instant(){return at;}}
