    @BeforeEach void setup(){clock.at=Instant.parse("2026-11-11T04:30:00Z");user=new User();user.setName("Paper ticket fixture");user.setEmail(UUID.randomUUID()+"@example.invalid");user.setRole("USER");user.setEmailVerified(true);user.setVirtualBalance(new BigDecimal("10000"));user=users.saveAndFlush(user);stock=new Stock();stock.setSymbol(UUID.randomUUID().toString());stock.setInstrumentKey("NSE_EQ|"+UUID.randomUUID());stock.setExchange("NSE");stock.setCurrentPrice(new BigDecimal("100"));stock=stocks.saveAndFlush(stock);quote("100");}
    @AfterEach void cleanup(){com.example.investsmart.settlement.SettlementTestCleanup.account(db,user.getId());for(String table:List.of("paper_fills","paper_finance_events","paper_tickets","paper_financing","option_orders","option_positions","auth_sessions","orders","holdings"))db.update("DELETE FROM "+table+" WHERE user_id=?",user.getId());users.deleteById(user.getId());stocks.deleteById(stock.getId());}
    void quote(String price){when(market.getQuote(any(MarketInstrument.class))).thenAnswer(call->new MarketQuote(stock.getSymbol(),new BigDecimal(price),null,clock.instant().atZone(com.example.investsmart.options.OptionMarket.INDIA).toLocalDateTime()).withInstrument(new MarketInstrument(stock.getInstrumentKey(),stock.getSymbol(),"Fixture","NSE")));}
    PaperTrading.Ticket ticket(String product,String kind,int quantity,String price,BigDecimal stop,BigDecimal target){return new PaperTrading.Ticket(stock.getId(),null,null,quantity,"BUY",product,"REGULAR",kind,"DAY",price==null?null:new BigDecimal(price),kind.startsWith("STOP")?new BigDecimal(price):null,1,stop,target,null,UUID.randomUUID().toString());}
    String submit(PaperTrading.Ticket t){return (String)paper.submit(user.getEmail(),t).get("id");}
    BigDecimal cash(){return users.findById(user.getId()).orElseThrow().getVirtualBalance();}
    void cash(String expected){assertEquals(0,cash().compareTo(new BigDecimal(expected)));}
    Map<String,Object> order(String id){return db.queryForMap("SELECT * FROM paper_tickets WHERE id=?",id);}
    @Test void previewAndDuplicateMarketExecutionReserveAndChargeOnce(){var t=ticket("CASH","MARKET",10,null,null,null);var preview=paper.preview(user.getEmail(),t);assertEquals(new BigDecimal("1050.32"),preview.get("requiredCash"));assertNotNull(preview.get("expiresAt"));cash("10000");String id=submit(t);assertEquals("FILLED",order(id).get("status"));paper.submit(user.getEmail(),t);cash("8999.70");assertEquals(10,holdings.findByUserIdAndStockId(user.getId(),stock.getId()).orElseThrow().getQuantity());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM paper_fills WHERE user_id=?",Integer.class,user.getId()));assertEquals(0,portfolio.getPortfolio(user.getId()).getTotalValue().compareTo(new BigDecimal("9999.70")));}
    @Test void icebergSequentialLegsCanBeCancelledWithoutRefundingFilledValue(){var t=new PaperTrading.Ticket(stock.getId(),null,null,9,"BUY","CASH","ICEBERG","MARKET","DAY",null,null,2,null,null,null,UUID.randomUUID().toString());String id=submit(t);assertEquals("PART_FILLED",order(id).get("status"));assertEquals(5,((Number)order(id).get("filled_units")).intValue());paper.cancel(user.getEmail(),id);paper.cancel(user.getEmail(),id);cash("9499.85");assertEquals(5,holdings.findByUserIdAndStockId(user.getId(),stock.getId()).orElseThrow().getQuantity());}
    @Test void icebergCompletesAllLegsOnceAndChargesEachFilledChild(){var t=new PaperTrading.Ticket(stock.getId(),null,null,9,"BUY","CASH","ICEBERG","LIMIT","DAY",new BigDecimal("100"),null,2,null,null,null,UUID.randomUUID().toString());String id=submit(t);paper.process(id);paper.process(id);paper.process(id);assertEquals("FILLED",order(id).get("status"));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM paper_fills WHERE ticket_id=?",Integer.class,id));cash("9099.73");}
    @Test void gttStopGapClaimsOcoButRetainsSharesUntilLimitCanFill(){String parent=submit(ticket("CASH","MARKET",10,null,new BigDecimal("10"),new BigDecimal("10")));String stop=db.queryForObject("SELECT id FROM paper_tickets WHERE parent_id=? AND order_kind='STOP_LIMIT'",String.class,parent);quote("80");paper.process(stop);assertEquals("TRIGGERED",order(stop).get("status"));assertEquals("DAY",order(stop).get("validity"));assertEquals(10,((Number)order(stop).get("reserved_units")).intValue());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM paper_tickets WHERE parent_id=? AND status='OCO_CANCELLED'",Integer.class,parent));var sell=new com.example.investsmart.dto.OrderRequest();sell.setStockId(stock.getId());sell.setQuantity(1);assertThrows(RuntimeException.class,()->legacy.sellStock(user.getEmail(),sell));quote("90");paper.process(stop);paper.process(stop);cash("8999.43");assertEquals(new BigDecimal("900.00"),db.queryForObject("SELECT SUM(remaining_credit) FROM settlement_obligations WHERE user_id=? AND credit_policy='RESTRICTED'",BigDecimal.class,user.getId()));}
    @Test void stopLimitActivatesWithoutFillingAboveLimitAndBuyStopMarketIsProtected(){var sl=ticket("CASH","STOP_LIMIT",10,"110",null,null);String id=submit(sl);quote("120");paper.process(id);assertEquals("TRIGGERED",order(id).get("status"));assertEquals(0,((Number)order(id).get("filled_units")).intValue());quote("109");paper.process(id);assertEquals("FILLED",order(id).get("status"));}
    @Test void iocCancelsUnfilledReservationAndExpiryRefundsOnlyOnce(){var t=new PaperTrading.Ticket(stock.getId(),null,null,10,"BUY","CASH","REGULAR","LIMIT","IOC",new BigDecimal("90"),null,1,null,null,null,UUID.randomUUID().toString());String id=submit(t);assertEquals("CANCELLED",order(id).get("status"));cash("10000");String day=submit(ticket("CASH","LIMIT",10,"90",null,null));clock.at=Instant.parse("2026-11-11T10:01:00Z");paper.process(day);paper.process(day);cash("10000");}
    @Test void mtfInterestCatchupAndRepaymentAreIdempotentAndPreserveNetEquity(){submit(ticket("MTF","MARKET",10,null,null,null));cash("9499.70");assertTrue(holdings.findByUserId(user.getId()).isEmpty());String id=paper.financed().getFirst();assertEquals(0,portfolio.getPortfolio(user.getId()).getTotalValue().compareTo(new BigDecimal("9999.70")));clock.at=clock.at.plus(Duration.ofDays(1));paper.accruePosition(id);paper.accruePosition(id);assertEquals(new BigDecimal("0.16"),db.queryForObject("SELECT interest FROM paper_financing WHERE id=?",BigDecimal.class,id));paper.requestClose(user.getEmail(),id);paper.manage(id);cash("9999.24");assertEquals(0,db.queryForObject("SELECT quantity FROM paper_financing WHERE id=?",Integer.class,id));}
    @Test void coverClosesAtCutoffAndGapLossCanLeaveNegativeCash(){user.setVirtualBalance(new BigDecimal("525.32"));users.saveAndFlush(user);submit(ticket("COVER","MARKET",10,null,new BigDecimal("10"),null));cash("25.02");var withdrawal=new com.example.investsmart.dto.WalletRequest();withdrawal.setAmount(new BigDecimal("25.02"));wallet.withdraw(user.getEmail(),withdrawal);String id=paper.financed().getFirst();quote("1");paper.manage(id);cash("-490");assertThrows(ResponseStatusException.class,()->submit(ticket("CASH","MARKET",1,null,null,null)));}
    @Test void invalidReplacementRollsBackCancellationAndFunds(){String id=submit(ticket("CASH","LIMIT",10,"90",null,null));BigDecimal before=cash();assertThrows(ResponseStatusException.class,()->paper.edit(user.getEmail(),id,ticket("CASH","LIMIT",0,"90",null,null)));assertEquals("PENDING",order(id).get("status"));assertEquals(before,cash());}
    @Test void competingReservationsCannotDoubleSpend()throws Exception{user.setVirtualBalance(new BigDecimal("1000"));users.saveAndFlush(user);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);Callable<Boolean> submit=()->{start.await();try{paper.submit(user.getEmail(),ticket("CASH","LIMIT",8,"100",null,null));return true;}catch(ResponseStatusException rejected){return false;}};try{var a=pool.submit(submit);var b=pool.submit(submit);start.countDown();assertEquals(1,(a.get(15,TimeUnit.SECONDS)?1:0)+(b.get(15,TimeUnit.SECONDS)?1:0));}finally{pool.shutdownNow();}}
    @Test void buyStopMarketCannotSpendAboveItsReservedPriceCeiling(){String id=submit(ticket("CASH","STOP_MARKET",10,"110",null,null));BigDecimal heldCash=cash();quote("120");paper.process(id);assertEquals("TRIGGERED",order(id).get("status"));assertEquals(heldCash,cash());quote("115");paper.process(id);assertEquals("FILLED",order(id).get("status"));cash("8849.65");}
    @Test void absoluteExitPricesArePreservedAndMtfExitsRepayTheirOwnPosition(){var t=new PaperTrading.Ticket(stock.getId(),null,null,10,"BUY","MTF","REGULAR","MARKET","DAY",null,null,1,null,null,null,UUID.randomUUID().toString(),new BigDecimal("90"),new BigDecimal("110"));String parent=submit(t);String target=db.queryForObject("SELECT id FROM paper_tickets WHERE parent_id=? AND order_kind='LIMIT'",String.class,parent);assertEquals(new BigDecimal("110.00"),order(target).get("limit_price"));quote("110");paper.process(target);assertEquals("FILLED",order(target).get("status"));assertEquals(0,db.queryForObject("SELECT SUM(quantity) FROM paper_financing WHERE user_id=?",Integer.class,user.getId()));cash("10099.37");}
    @Test void coverEntryCannotFillAfterItsClosureCutoff(){String id=submit(ticket("COVER","LIMIT",10,"90",new BigDecimal("10"),null));clock.at=Instant.parse("2026-11-11T09:51:00Z");quote("89");paper.process(id);assertEquals("EXPIRED",order(id).get("status"));cash("10000");assertTrue(paper.financed().stream().noneMatch(x->positionOwner(x)));}
    boolean positionOwner(String id){return db.queryForObject("SELECT user_id FROM paper_financing WHERE id=?",Long.class,id).equals(user.getId());}
    @Test void ownershipAndStaleQuoteChecksCannotMutateAnotherAccount(){String id=submit(ticket("CASH","LIMIT",10,"90",null,null));var other=new User();other.setName("Other");other.setEmail(UUID.randomUUID()+"@example.invalid");other.setRole("USER");other.setVirtualBalance(BigDecimal.ZERO);other=users.saveAndFlush(other);try{String email=other.getEmail();assertEquals(404,assertThrows(ResponseStatusException.class,()->paper.cancel(email,id)).getStatusCode().value());}finally{users.deleteById(other.getId());}BigDecimal before=cash();when(market.getQuote(any(MarketInstrument.class))).thenReturn(new MarketQuote(stock.getSymbol(),new BigDecimal("89"),null,clock.instant().minusSeconds(120).atZone(com.example.investsmart.options.OptionMarket.INDIA).toLocalDateTime()).withInstrument(new MarketInstrument(stock.getInstrumentKey(),stock.getSymbol(),"Fixture","NSE")));assertThrows(com.example.investsmart.exception.MarketStatusUnavailableException.class,()->paper.process(id));assertEquals(before,cash());assertEquals("PENDING",order(id).get("status"));}
    @Test void newSchemaMigrationIsRerunnableAndPreservesLegacyBalances()throws Exception{try(var connection=java.sql.DriverManager.getConnection("jdbc:h2:mem:paper-upgrade-"+UUID.randomUUID()+";MODE=MySQL")){var st=connection.createStatement();st.execute("CREATE TABLE users(id BIGINT PRIMARY KEY,virtual_balance DECIMAL(19,2))");st.execute("INSERT INTO users VALUES(1,1234.56)");var migration=new org.springframework.jdbc.datasource.init.ResourceDatabasePopulator(new org.springframework.core.io.ClassPathResource("db/migrations/20261111_paper_ticket.sql"));migration.populate(connection);migration.populate(connection);var rs=st.executeQuery("SELECT virtual_balance FROM users WHERE id=1");assertTrue(rs.next());assertEquals(new BigDecimal("1234.56"),rs.getBigDecimal(1));}}
    @Test void optionIcebergUsesLotsAndFreshDepthAndSharesOcoReservations(){
        var expiry=LocalDate.of(2026,11,18);var contract=new com.example.investsmart.options.OptionMarket.Contract("NSE_FO|123","Fixture CE",expiry,new BigDecimal("24000"),"CE",50,100);
        var q=new com.example.investsmart.options.OptionMarket.Quote(contract,new BigDecimal("10"),new BigDecimal("9"),new BigDecimal("10"),500,500,null,null,clock.instant());when(optionMarket.chain(expiry)).thenReturn(List.of(q));
        var t=new PaperTrading.Ticket(null,contract.instrumentKey(),expiry,150,"BUY","CASH","ICEBERG","MARKET","DAY",null,null,2,new BigDecimal("10"),new BigDecimal("10"),null,UUID.randomUUID().toString());String id=submit(t);assertEquals(100,((Number)order(id).get("filled_units")).intValue());paper.process(id);paper.process(id);cash("8499.55");assertEquals(150,db.queryForObject("SELECT units FROM option_positions WHERE user_id=?",Integer.class,user.getId()));assertEquals(150,db.queryForObject("SELECT SUM(reserved_units) FROM paper_tickets WHERE parent_id=?",Integer.class,id));
        for(String fillId:db.queryForList("SELECT id FROM paper_fills WHERE ticket_id=?",String.class,id)){
            var overlap=optionLegacyEvidence.read(user.getEmail(),fillId);
            assertEquals(com.example.investsmart.dto.OptionLegacyEvidence.Verification.MATCHED_DUPLICATE,overlap.verification());
            assertEquals(db.queryForObject("SELECT legacy_order_id FROM paper_fills WHERE id=?",String.class,fillId),overlap.duplicateOptionOrderId());
        }
        var sell=new com.example.investsmart.options.OptionTrading.Ticket(contract.instrumentKey(),expiry,"SELL","MARKET",1,null,UUID.randomUUID().toString());assertThrows(ResponseStatusException.class,()->optionsForTest().submit(user.getEmail(),sell));
    }
