    @Test void missingOptionDepthRollsBackTheNewReservation(){var expiry=LocalDate.of(2026,11,18);var contract=new com.example.investsmart.options.OptionMarket.Contract("NSE_FO|124","Fixture PE",expiry,new BigDecimal("24000"),"PE",50,100);when(optionMarket.chain(expiry)).thenReturn(List.of(new com.example.investsmart.options.OptionMarket.Quote(contract,BigDecimal.TEN,BigDecimal.TEN,BigDecimal.TEN,1,1,null,null,clock.instant())));assertThrows(ResponseStatusException.class,()->submit(new PaperTrading.Ticket(null,contract.instrumentKey(),expiry,50,"BUY","CASH","REGULAR","MARKET","DAY",null,null,1,null,null,null,UUID.randomUUID().toString())));cash("10000");assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM paper_tickets WHERE user_id=?",Integer.class,user.getId()));}
    @Test void longInterestCatchupIsBoundedAndResumesWithoutDuplicateDates(){submit(ticket("MTF","MARKET",10,null,null,null));String id=paper.financed().getFirst();clock.at=clock.at.plus(Duration.ofDays(40));paper.accruePosition(id);assertEquals(31,db.queryForObject("SELECT COUNT(*) FROM paper_finance_events WHERE position_id=? AND event_type='INTEREST'",Integer.class,id));assertNull(paper.summary(user.getId()).get("value"));paper.accruePosition(id);paper.accruePosition(id);assertEquals(40,db.queryForObject("SELECT COUNT(*) FROM paper_finance_events WHERE position_id=? AND event_type='INTEREST'",Integer.class,id));assertEquals(new BigDecimal("6.40"),db.queryForObject("SELECT interest FROM paper_financing WHERE id=?",BigDecimal.class,id));}
    @Test void paperApiRequiresSessionAndCsrfAndReturnsServerPreview()throws Exception{
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get("/orders/paper")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isUnauthorized());
        var cookie=new jakarta.servlet.http.Cookie(com.example.investsmart.security.SecurityAccounts.COOKIE,accounts.issue(user,new org.springframework.mock.web.MockHttpServletRequest(),new org.springframework.mock.web.MockHttpServletResponse()));
        String body=json.writeValueAsString(ticket("CASH","LIMIT",10,"90",null,null));
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/orders/paper").cookie(cookie).contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isForbidden());
        mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/orders/paper/preview").cookie(cookie).with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.requiredCash").value(900.27));
        cash("10000");mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/orders/paper").cookie(cookie).with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf()).contentType("application/json").content(body)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isOk()).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath("$.status").value("PENDING"));cash("9099.73");
    }
    @Test void ocoTriggerSurvivesAFillRejectionWithoutCommittingAFinancialMutation(){String parent=submit(ticket("CASH","MARKET",10,null,new BigDecimal("10"),new BigDecimal("10")));String stop=db.queryForObject("SELECT id FROM paper_tickets WHERE parent_id=? AND order_kind='STOP_LIMIT'",String.class,parent);var q90=new MarketQuote(stock.getSymbol(),new BigDecimal("90"),null,clock.instant().atZone(com.example.investsmart.options.OptionMarket.INDIA).toLocalDateTime()).withInstrument(new MarketInstrument(stock.getInstrumentKey(),stock.getSymbol(),"Fixture","NSE"));var q85=new MarketQuote(stock.getSymbol(),new BigDecimal("85"),null,q90.getLastUpdated()).withInstrument(new MarketInstrument(stock.getInstrumentKey(),stock.getSymbol(),"Fixture","NSE"));when(market.getQuote(any(MarketInstrument.class))).thenReturn(q90,q90,q85);assertThrows(RuntimeException.class,()->paper.process(stop));cash("8999.70");assertEquals("TRIGGERED",order(stop).get("status"));assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM paper_tickets WHERE parent_id=? AND status='OCO_CANCELLED'",Integer.class,parent));quote("90");paper.process(stop);cash("8999.43");assertEquals(new BigDecimal("900.00"),db.queryForObject("SELECT SUM(remaining_credit) FROM settlement_obligations WHERE user_id=? AND credit_policy='RESTRICTED'",BigDecimal.class,user.getId()));}
